-- +goose Up
-- Finished products are distinct from consumable stock and shared tools.
-- The identity-backed code is stable, unique, and generated by the database.
CREATE TABLE manufacturing_production_batches (
    request_id UUID PRIMARY KEY,
    execution_id BIGINT NOT NULL REFERENCES manufacturing_executions(id) ON DELETE RESTRICT,
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    actor_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE finished_product_units (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code TEXT GENERATED ALWAYS AS ('PRD-' || lpad(id::TEXT, GREATEST(6, length(id::TEXT)), '0')) STORED UNIQUE,
    execution_id BIGINT NOT NULL REFERENCES manufacturing_executions(id) ON DELETE RESTRICT,
    production_request_id UUID NOT NULL REFERENCES manufacturing_production_batches(request_id) ON DELETE RESTRICT,
    produced_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX finished_product_units_execution_idx ON finished_product_units(execution_id, id);
CREATE INDEX finished_product_units_batch_idx ON finished_product_units(production_request_id, id);

-- +goose Down
-- +goose StatementBegin
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM manufacturing_production_batches) OR EXISTS (SELECT 1 FROM finished_product_units) THEN
        RAISE EXCEPTION 'cannot roll back finished products while production history exists';
    END IF;
END $$;
-- +goose StatementEnd
DROP TABLE finished_product_units;
DROP TABLE manufacturing_production_batches;
